// Saved scripts live in this browser only. Every access is wrapped because
// storage can be unavailable (private windows, embedded previews).

export type SavedScript = {
  id: string;
  name: string;
  source: string;
  updatedAt: number;
};

const SCRIPTS_KEY = 'sandscript.scripts.v1';
const DRAFT_KEY = 'sandscript.draft.v1';

function read<T>(key: string, fallback: T): T {
  try {
    const raw = localStorage.getItem(key);
    return raw ? (JSON.parse(raw) as T) : fallback;
  } catch {
    return fallback;
  }
}

function write(key: string, value: unknown): boolean {
  try {
    localStorage.setItem(key, JSON.stringify(value));
    return true;
  } catch {
    return false;
  }
}

export function loadScripts(): SavedScript[] {
  const scripts = read<SavedScript[]>(SCRIPTS_KEY, []);
  return Array.isArray(scripts) ? scripts.sort((a, b) => b.updatedAt - a.updatedAt) : [];
}

export function saveScripts(scripts: SavedScript[]): boolean {
  return write(SCRIPTS_KEY, scripts);
}

export type Draft = { name: string; source: string; scriptId: string | null };

export function loadDraft(): Draft | null {
  return read<Draft | null>(DRAFT_KEY, null);
}

export function saveDraft(draft: Draft) {
  write(DRAFT_KEY, draft);
}

export function readPreference(key: string): string | null {
  try {
    return localStorage.getItem(key);
  } catch {
    return null;
  }
}

export function writePreference(key: string, value: string) {
  try {
    localStorage.setItem(key, value);
  } catch {
    // preference simply won't persist
  }
}

export function newId(): string {
  return `${Date.now().toString(36)}${Math.random().toString(36).slice(2, 7)}`;
}
